    """Project non-background markers along paired, equal-length edge bars."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    def runs(side):
        vals = ([grid[0][c] for c in range(w)] if side == 'top' else
                [grid[h - 1][c] for c in range(w)] if side == 'bottom' else
                [grid[r][0] for r in range(h)] if side == 'left' else
                [grid[r][w - 1] for r in range(h)])
        result, i = [], 0
        while i < len(vals):
            if vals[i] == bg:
                i += 1
                continue
            j = i + 1
            while j < len(vals) and vals[j] == vals[i]:
                j += 1
            if j - i >= 2:
                result.append((vals[i], i, j))
            i = j
        return result

    edge = {side: runs(side) for side in ('top', 'bottom', 'left', 'right')}
    pairs = []
    for a, b in (('left', 'right'), ('top', 'bottom')):
        for color, start, end in edge[a]:
            for color2, start2, end2 in edge[b]:
                if color == color2 and end - start == end2 - start2:
                    pairs.append((a, start, end, b, start2, end2))

    bar_cells = set()
    for side, segments in edge.items():
        for _, start, end in segments:
            for i in range(start, end):
                bar_cells.add((0, i) if side == 'top' else
                              (h - 1, i) if side == 'bottom' else
                              (i, 0) if side == 'left' else (i, w - 1))

    for a, start, end, b, start2, end2 in pairs:
        vertical = a in ('left', 'right')
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg or (r, c) in bar_cells:
                    continue
                axis = r if vertical else c
                if start <= axis < end:
                    source, source_start, counterpart, counterpart_start = a, start, b, start2
                elif start2 <= axis < end2:
                    source, source_start, counterpart, counterpart_start = b, start2, a, start
                else:
                    continue
                mapped = counterpart_start + axis - source_start
                if vertical:
                    # Fill from the marker toward the edge bar it aligns with.
